1	//! Free-form measurement probe: a named, single-writer histogram
2	//! of sample durations in nanoseconds.
3	//!
4	//! The caller captures endpoints with any time source (typically
5	//! `minstant::Instant::now()`) and feeds the elapsed delta to
6	//! [`Probe::record`]. At report time [`Probe::report`] renders a
7	//! band-table summary under the enclosing bench's report, using
8	//! the same percentile boundaries so columns line up visually.
9	
10	use hdrhistogram::Histogram;
11	
12	use crate::harness::{fmt_commas, fmt_commas_f64};
13	
14	const BOUNDARY_PCTS: &[f64] = &[
15	    0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
16	];
17	const BOUNDARY_NAMES: &[&str] = &[
18	    "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
19	];
20	
21	/// A named, single-writer nanosecond histogram. Not `Sync`;
22	/// cross-thread *sharing* is out of scope. `Send` so probes can
23	/// be moved between threads (e.g. returned via a
24	/// `JoinHandle<Probe>` on shutdown).
25	pub struct Probe {
26	    name: String,
27	    hist: Histogram<u64>,
28	}
29	
30	impl Probe {
31	    /// Create an empty probe. Histogram bounds (1 ns — 60 s,
32	    /// 3 significant figures) mirror the harness.
33	    pub fn new(name: &str) -> Self {
34	        Self {
35	            name: name.to_string(),
36	            hist: Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
37	        }
38	    }
39	
40	    /// Record a single sample. Values of 0 are clamped to 1 since
41	    /// the histogram's lower bound is 1 ns; sub-ns deltas from
42	    /// coarse timers round up rather than panic.
43	    pub fn record(&mut self, ns: u64) {
44	        self.hist.record(ns.max(1)).unwrap();
45	    }
46	
47	    /// Render a band-table report for this probe, indented one
48	    /// level deeper than the enclosing bench's report. No
49	    /// `adjusted` column — probe overhead subtraction is a
50	    /// separate concern.
51	    pub fn report(&self) {
52	        let sample_count = self.hist.len();
53	        println!(
54	            "  probe: {} [count={}]",
55	            self.name,
56	            fmt_commas(sample_count)
57	        );
58	        if sample_count == 0 {
59	            println!();
60	            return;
61	        }
62	
63	        let n_bands = BOUNDARY_PCTS.len() - 1;
64	        let mut band_first = vec![u64::MAX; n_bands];
65	        let mut band_last = vec![0u64; n_bands];
66	        let mut band_count = vec![0u64; n_bands];
67	        let mut band_sum = vec![0u128; n_bands];
68	
69	        let mut cumulative = 0u64;
70	        for iv in self.hist.iter_recorded() {
71	            let value = iv.value_iterated_to();
72	            let count = iv.count_at_value();
73	            let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
74	            let idx = BOUNDARY_PCTS[1..]
75	                .iter()
76	                .position(|&b| mid_rank < b)
77	                .unwrap_or(n_bands - 1);
78	            band_first[idx] = band_first[idx].min(value);
79	            band_last[idx] = band_last[idx].max(value);
80	            band_count[idx] += count;
81	            band_sum[idx] += value as u128 * count as u128;
82	            cumulative += count;
83	        }
84	
85	        struct BandRow {
86	            label: String,
87	            first: String,
88	            last: String,
89	            range: String,
90	            count: String,
91	            mean: String,
92	        }
93	
94	        let mut rows: Vec<BandRow> = Vec::new();
95	        for i in 0..n_bands {
96	            if band_count[i] == 0 {
97	                continue;
98	            }
99	            let mean_val = band_sum[i] as f64 / band_count[i] as f64;
100	            rows.push(BandRow {
101	                label: format!("{}-{}", BOUNDARY_NAMES[i], BOUNDARY_NAMES[i + 1]),
102	                first: fmt_commas(band_first[i]),
103	                last: fmt_commas(band_last[i]),
104	                range: fmt_commas(band_last[i] - band_first[i] + 1),
105	                count: fmt_commas(band_count[i]),
106	                mean: fmt_commas_f64(mean_val, 0),
107	            });
108	        }
109	
110	        let label_w = rows
111	            .iter()
112	            .map(|r| r.label.len())
113	            .max()
114	            .unwrap_or(0)
115	            .max("stdev min-p99".len());
116	        let first_w = rows.iter().map(|r| r.first.len()).max().unwrap_or(0);
117	        let last_w = rows.iter().map(|r| r.last.len()).max().unwrap_or(0);
118	        let range_w = rows.iter().map(|r| r.range.len()).max().unwrap_or(0);
119	        let count_w = rows.iter().map(|r| r.count.len()).max().unwrap_or(0);
120	        let mean_w = rows.iter().map(|r| r.mean.len()).max().unwrap_or(0);
121	
122	        const INDENT: &str = "    ";
123	        const GAP: &str = "    ";
124	
125	        let first_col = INDENT.len() + label_w + 1 + first_w;
126	        let last_gap = " ns".len() + GAP.len() + last_w;
127	        let range_gap = " ns".len() + GAP.len() + range_w;
128	        let count_gap = " ns".len() + GAP.len() + count_w;
129	        let mean_gap = GAP.len() + mean_w;
130	        println!(
131	            "{:>first_col$}{:>last_gap$}{:>range_gap$}{:>count_gap$}{:>mean_gap$}",
132	            "first", "last", "range", "count", "mean",
133	        );
134	
135	        for r in &rows {
136	            println!(
137	                "{INDENT}{:<label_w$} {:>first_w$} ns{GAP}{:>last_w$} ns{GAP}{:>range_w$} ns{GAP}{:>count_w$}{GAP}{:>mean_w$} ns",
138	                r.label, r.first, r.last, r.range, r.count, r.mean,
139	            );
140	        }
141	
142	        let hist_mean = self.hist.mean();
143	        let skip = first_w
144	            + " ns".len()
145	            + GAP.len()
146	            + last_w
147	            + " ns".len()
148	            + GAP.len()
149	            + range_w
150	            + " ns".len()
151	            + GAP.len()
152	            + count_w;
153	        println!(
154	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
155	            "mean",
156	            "",
157	            fmt_commas_f64(hist_mean, 0),
158	        );
159	        println!(
160	            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} ns",
161	            "stdev",
162	            "",
163	            fmt_commas_f64(self.hist.stdev(), 0),
164	        );
165	
166	        let trim_count: u64 = band_count[..n_bands - 1].iter().sum();
167	        if trim_count > 0 {
168	            let trim_sum: u128 = band_sum[..n_bands - 1].iter().sum();
169	            let trim_mean = trim_sum as f64 / trim_count as f64;
170	
171	            let mut trim_var_sum = 0.0f64;
172	            let mut trim_var_count = 0u64;
173	            let mut cum = 0u64;
174	            for iv in self.hist.iter_recorded() {
175	                let value = iv.value_iterated_to();
176	                let count = iv.count_at_value();
177	                let mid_rank = (cum as f64 + count as f64 / 2.0) / sample_count as f64;
178	                let idx = BOUNDARY_PCTS[1..]
179	                    .iter()
180	                    .position(|&b| mid_rank < b)
181	                    .unwrap_or(n_bands - 1);
182	                if idx < n_bands - 1 {
