1	mod benches;
2	mod harness;
3	mod overhead;
4	mod pin;
5	mod probe;
6	
7	use clap::Parser;
8	use log::{debug, info};
9	
10	#[derive(Parser)]
11	#[command(
12	    version,
13	    about = concat!(
14	        "iiac-perf ",
15	        env!("CARGO_PKG_VERSION"),
16	        " — Rust latency microbenchmark harness",
17	    ),
18	    max_term_width = 80,
19	)]
20	struct Cli {
21	    /// Benches to run. Pass 'all' for every registered bench, or
22	    /// one or more names. Run with no args to see the available list.
23	    benches: Vec<String>,
24	
25	    /// Target wall-clock seconds per bench (default 5.0). Auto-sizes
26	    /// outer and inner loop counts. Mutually exclusive with -D.
27	    #[arg(short = 'd', long, conflicts_with = "total_duration")]
28	    duration: Option<f64>,
29	
30	    /// Target total wall-clock seconds across all requested benches;
31	    /// budget is split equally per bench. Mutually exclusive with -d.
32	    #[arg(short = 'D', long)]
33	    total_duration: Option<f64>,
34	
35	    /// Override outer loop count (skips auto-sizing; inner still adapts).
36	    #[arg(short, long)]
37	    outer: Option<u64>,
38	
39	    /// Override inner loop count (skips auto-sizing).
40	    /// inner=1 measures single-call latency (each sample = one step); higher
41	    /// inner measures back-to-back/burst rate (each sample = N steps averaged).
42	    #[arg(short, long)]
43	    inner: Option<u64>,
44	
45	    /// Pin bench threads to logical CPUs (comma-separated, ranges OK).
46	    /// The list is a core *pool*: thread `i` of a bench is pinned to
47	    /// `pool[i % pool.len()]`, so shorter pools oversubscribe by wrap.
48	    /// Examples: `--pin 0,1` (2 threads → 2 CPUs), `--pin 0-5` (6-thread
49	    /// pool), `--pin 0,0` (two threads on the same CPU). On 3900X,
50	    /// logical CPUs N and N+12 are SMT siblings of the same physical
51	    /// core — `--pin 0,12` pairs siblings (max contention), `--pin 0,1`
52	    /// gives independent cores. Omit to leave threads unpinned.
53	    #[arg(long, value_name = "CORES")]
54	    pin: Option<String>,
55	
56	    /// Skip pinning the main thread for calibration. Always takes
57	    /// effect, including when `--pin` is set — bench threads still
58	    /// pin per `--pin`, but main stays on whatever affinity mask
59	    /// the process launched with. By default (without this flag),
60	    /// calibration runs with main pinned to `pin[0]` if set, else
61	    /// core 0, so framing/loop come from a stable environment.
62	    /// Pass this flag to decouple the calibration environment from
63	    /// the bench pinning pool (or to reproduce pre-0.6.0 behavior
64	    /// when `--pin` is absent).
65	    #[arg(long)]
66	    no_pin_cal: bool,
67	
68	    /// Enable verbose internals on stderr: affinity mask, cal
69	    /// parameters and raw fit inputs, calibration wall time.
70	    /// Equivalent to `RUST_LOG=debug`. Default is `warn` (silent
71	    /// unless something's wrong). `RUST_LOG` overrides this flag
72	    /// when set, so per-module filtering still works.
73	    #[arg(short, long)]
74	    verbose: bool,
75	}
76	
77	const DEFAULT_DURATION: f64 = 5.0;
78	
79	fn main() {
80	    let cli = Cli::parse();
81	
82	    // Default filter is `warn`; `-v` bumps to `debug`. `RUST_LOG`
83	    // (if set) always wins — so users can still do fine-grained
84	    // per-module filtering without fighting the flag.
85	    let mut builder = env_logger::Builder::from_default_env();
86	    if std::env::var_os("RUST_LOG").is_none() {
87	        builder.filter_level(if cli.verbose {
88	            log::LevelFilter::Debug
89	        } else {
90	            log::LevelFilter::Warn
91	        });
92	    }
93	    builder.format_timestamp(None).init();
94	
95	    if cli.benches.is_empty() {
96	        println!("no benches specified. use -h or --help for more info.");
97	        println!("available: all, {}", benches::names().join(", "));
98	        return;
99	    }
100	
101	    println!(
102	        "iiac-perf {} — Rust latency microbenchmark harness\n",
103	        env!("CARGO_PKG_VERSION")
104	    );
105	
106	    if let Some(mask) = pin::current_affinity() {
107	        info!("startup affinity: {}", pin::affinity_summary(&mask));
108	    }
109	
110	    let pin_cores: Vec<usize> = match cli.pin.as_deref() {
111	        None => Vec::new(),
112	        Some(spec) => match pin::parse_cores(spec) {
113	            Ok(v) => v,
114	            Err(e) => {
115	                eprintln!("error: --pin: {e}");
116	                std::process::exit(2);
117	            }
118	        },
119	    };
120	
121	    // Pin main for calibration. Always pinned by default so
122	    // framing/loop numbers come from a stable environment
123	    // regardless of --pin. --no-pin-cal restores pre-0.6.0
124	    // behavior (pin iff --pin given).
125	    //
126	    // When we're doing the cal-only pin (--pin absent, --no-pin-cal
127	    // absent), snapshot the pre-cal affinity and restore it after
128	    // calibrate() so the scheduler regains freedom to co-locate
129	    // bench threads — otherwise main's pin leaks into the
130	    // scheduler's placement decisions and suppresses the
131	    // "both ends hot and spinning" fast path.
132	    let cal_pin: Option<usize> = if cli.no_pin_cal {
133	        None
134	    } else {
135	        pin_cores.first().copied().or(Some(0))
136	    };
137	    // Save/restore pre-cal affinity whenever we're about to set a
138	    // cal pin that wasn't the user's explicit bench-pin request —
139	    // i.e. the cal-only pin (--pin absent, --no-pin-cal absent).
140	    // --pin ⇒ user already wants main on pin[0]; leave alone.
141	    // --no-pin-cal ⇒ we aren't pinning at all; nothing to save.
142	    let saved_affinity = if pin_cores.is_empty() && !cli.no_pin_cal {
143	        pin::save_affinity()
144	    } else {
145	        None
146	    };
147	    pin::pin_current(cal_pin);
148	
149	    if let Some(cpu) = cal_pin {
150	        info!("pinned main to core {cpu} for calibration");
151	    } else {
152	        info!("cal pin skipped");
153	    }
154	    if let Some(mask) = pin::current_affinity() {
155	        debug!("affinity during cal: {}", pin::affinity_summary(&mask));
156	    }
157	
158	    let amp_coeff = overhead::N_HIGH as f64 / (overhead::N_HIGH - overhead::N_LOW) as f64;
159	    info!(
160	        "calibration params: warmup={}, samples={}, N_LOW={}, N_HIGH={}, noise_amp={:.4}",
161	        overhead::CAL_WARMUP,
162	        overhead::CAL_SAMPLES,
163	        overhead::N_LOW,
164	        overhead::N_HIGH,
165	        amp_coeff,
166	    );
167	
168	    let overhead = overhead::calibrate();
169	
170	    debug!(
171	        "calibration raw: min_low={} ns, min_high={} ns",
172	        overhead.cal_min_low_ns, overhead.cal_min_high_ns,
173	    );
174	    debug!(
175	        "calibration fit: framing={:.4} ns, loop_per_iter={:.4} ns",
176	        overhead.framing_per_sample_ns, overhead.loop_per_iter_ns,
177	    );
178	    info!(
179	        "calibration wall time: {:.2} ms",
180	        overhead.cal_duration.as_secs_f64() * 1000.0
181	    );
182	
183	    if let Some(set) = saved_affinity.as_ref() {
184	        pin::restore_affinity(set);
185	    }
186	
187	    let cal_pin_display = match (pin_cores.first(), cli.no_pin_cal) {
188	        (_, true) => "none (--no-pin-cal)".to_string(),
189	        (Some(c), false) => format!("core {c} (from --pin)"),
190	        (None, false) => "core 0 (unpinned after cal; --no-pin-cal to skip)".to_string(),
191	    };
192	    println!("Calibration:");
193	    println!(
194	        "  framing/sample    {:>7} ns  (timer pair, two-point fit)",
195	        harness::fmt_commas_f64(overhead.framing_per_sample_ns, 2)
196	    );
197	    println!(
198	        "  loop/iter         {:>7} ns  (per inner-loop iteration)",
199	        harness::fmt_commas_f64(overhead.loop_per_iter_ns, 2)
200	    );
201	    println!("  cal pin           {cal_pin_display}");
202	    println!("  bench pin         {}", pin::plan_summary(&pin_cores));
203	    println!();
204	
205	    let runners = match benches::resolve(&cli.benches) {
206	        Ok(r) => r,
207	        Err(e) => {
208	            eprintln!("error: {e}");
209	            std::process::exit(2);
210	        }
211	    };
212	
213	    let target_seconds = match (cli.duration, cli.total_duration) {
214	        (Some(d), _) => d,
215	        (None, Some(t)) => t / runners.len() as f64,
216	        (None, None) => DEFAULT_DURATION,
217	    };
218	
219	    let cfg = harness::RunCfg {
220	        overhead: &overhead,
