/// Create an empty probe. Histogram bounds (1 ns — 60 s,
/// 3 significant figures) mirror the harness.
///
/// Panics if invariant TSC isn't available on this CPU —
/// `minstant::Instant::now()` would silently fall back to
/// `clock_gettime`, which is ~20× slower and would poison
/// every sample.
pub fn new(name: &str) -> Self {
    assert!(
        minstant::is_tsc_available(),
        "Probe requires invariant TSC; minstant would fall back to clock_gettime"
    );
    Self {
        name: name.to_string(),
        hist: Histogram::<u64>::new_with_bounds(1, 60_000_000_000, 3).unwrap(),
    }
}

