//! Skipping the TSC→ns conversion at record time trims a mul-shift
//! from the hot path; conversion to nanoseconds, if desired, is
//! deferred to the report phase.

use hdrhistogram::Histogram;

use crate::harness::{fmt_commas, fmt_commas_f64};

const BOUNDARY_PCTS: &[f64] = &[
    0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
];
const BOUNDARY_NAMES: &[&str] = &[
    "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
];

/// A named, single-writer histogram of TSC-tick deltas. Not
/// `Sync`; cross-thread *sharing* is out of scope. `Send` so
/// probes can be moved between threads (e.g. returned via a
/// `JoinHandle<TProbe>` on shutdown).
pub struct TProbe {
    name: String,
    hist: Histogram<u64>,
}

impl TProbe {
    /// Create an empty probe. Histogram upper bound is 1e12
    /// ticks (~250 s at 4 GHz, ~100 s at 10 GHz), 3 significant
    /// figures.
    ///
    /// Panics if invariant TSC isn't available on this CPU —
    /// a tick-based probe without invariant TSC is meaningless.
    pub fn new(name: &str) -> Self {
        assert!(
            minstant::is_tsc_available(),
            "TProbe requires invariant TSC"
        );
        Self {
            name: name.to_string(),
            hist: Histogram::<u64>::new_with_bounds(1, 1_000_000_000_000, 3).unwrap(),
        }
    }

    /// Record a single sample, in TSC ticks. Values of 0 are
    /// clamped to 1 since the histogram's lower bound is 1; a
    /// back-to-back `rdtsc` pair can produce 0 on fast cores.
    pub fn record(&mut self, ticks: u64) {
        self.hist.record(ticks.max(1)).unwrap();
    }

    /// Render a band-table report for this probe, indented one
    /// level deeper than the enclosing bench's report. Values are
    /// in TSC ticks (`tk`). No `adjusted` column — probe overhead
    /// subtraction is a separate concern.
    pub fn report(&self) {
        let sample_count = self.hist.len();
        println!(
            "  tprobe: {} [count={}]",
            self.name,
            fmt_commas(sample_count)
        );
        if sample_count == 0 {
            println!();
            return;
        }

        let n_bands = BOUNDARY_PCTS.len() - 1;
        let mut band_first = vec![u64::MAX; n_bands];
        let mut band_last = vec![0u64; n_bands];
        let mut band_count = vec![0u64; n_bands];
        let mut band_sum = vec![0u128; n_bands];

        let mut cumulative = 0u64;
        for iv in self.hist.iter_recorded() {
            let value = iv.value_iterated_to();
            let count = iv.count_at_value();
            let mid_rank = (cumulative as f64 + count as f64 / 2.0) / sample_count as f64;
            let idx = BOUNDARY_PCTS[1..]
                .iter()
                .position(|&b| mid_rank < b)
                .unwrap_or(n_bands - 1);
            band_first[idx] = band_first[idx].min(value);
            band_last[idx] = band_last[idx].max(value);
            band_count[idx] += count;
            band_sum[idx] += value as u128 * count as u128;
            cumulative += count;
        }

