    #[arg(short, long)]
    outer: Option<u64>,

    /// Override inner loop count (skips auto-sizing).
    /// inner=1 measures single-call latency (each sample = one step); higher
    /// inner measures back-to-back/burst rate (each sample = N steps averaged).
    #[arg(short, long)]
    inner: Option<u64>,

