1	//! Free-form measurement probe: a named, single-writer histogram
2	//! of sample durations in raw TSC ticks.
3	//!
4	//! Same shape as [`crate::probe::Probe`], but the caller records
5	//! tick deltas (`rdtsc_end − rdtsc_start`) rather than nanoseconds.
6	//! Skipping the TSC→ns conversion at record time trims a mul-shift
7	//! from the hot path; conversion to nanoseconds, if desired, is
8	//! deferred to the report phase via a one-time
9	//! [`ticks_per_ns`] calibration.
10	
11	use std::sync::OnceLock;
12	use std::time::Duration;
13	
14	use hdrhistogram::Histogram;
15	
16	use crate::harness::{fmt_commas, fmt_commas_f64};
17	
18	const BOUNDARY_PCTS: &[f64] = &[
19	    0.0, 0.01, 0.10, 0.20, 0.30, 0.40, 0.50, 0.60, 0.70, 0.80, 0.90, 0.99, 1.0,
20	];
21	const BOUNDARY_NAMES: &[&str] = &[
22	    "min", "p1", "p10", "p20", "p30", "p40", "p50", "p60", "p70", "p80", "p90", "p99", "max",
23	];
24	
25	/// Cached TSC→ns ratio. `minstant` computes this internally but
26	/// doesn't expose it; we rederive it once by spinning for ~10 ms
27	/// and comparing a `minstant::Instant` delta to a raw `rdtsc`
28	/// delta.
29	static TICKS_PER_NS: OnceLock<f64> = OnceLock::new();
30	
31	fn ticks_per_ns() -> f64 {
32	    *TICKS_PER_NS.get_or_init(|| {
33	        let start_instant = minstant::Instant::now();
34	        let start_tsc = unsafe { core::arch::x86_64::_rdtsc() };
35	        let target = Duration::from_millis(10);
36	        loop {
37	            let elapsed = start_instant.elapsed();
38	            if elapsed >= target {
39	                let end_tsc = unsafe { core::arch::x86_64::_rdtsc() };
40	                let dtk = end_tsc.wrapping_sub(start_tsc) as f64;
41	                let dns = elapsed.as_nanos() as f64;
42	                return dtk / dns;
43	            }
44	            core::hint::spin_loop();
45	        }
46	    })
47	}
48	
49	/// A named, single-writer histogram of TSC-tick deltas. Not
50	/// `Sync`; cross-thread *sharing* is out of scope. `Send` so
51	/// probes can be moved between threads (e.g. returned via a
52	/// `JoinHandle<TProbe>` on shutdown).
53	pub struct TProbe {
54	    name: String,
55	    hist: Histogram<u64>,
56	}
57	
58	impl TProbe {
59	    /// Create an empty probe. Histogram upper bound is 1e12
60	    /// ticks (~250 s at 4 GHz, ~100 s at 10 GHz), 3 significant
61	    /// figures.
62	    ///
63	    /// Exits the process (code 1) if TSC isn't suitable for
64	    /// probing — see [`crate::tsc::require_tsc_ok`].
65	    pub fn new(name: &str) -> Self {
66	        crate::tsc::require_tsc_ok();
67	        // Trigger calibration eagerly so the first report() doesn't
68	        // pay for it.
69	        let _ = ticks_per_ns();
70	        Self {
71	            name: name.to_string(),
72	            hist: Histogram::<u64>::new_with_bounds(1, 1_000_000_000_000, 3).unwrap(),
73	        }
74	    }
75	
76	    /// Record a single sample, in TSC ticks. Values of 0 are
77	    /// clamped to 1 since the histogram's lower bound is 1; a
78	    /// back-to-back `rdtsc` pair can produce 0 on fast cores.
79	    pub fn record(&mut self, ticks: u64) {
80	        self.hist.record(ticks.max(1)).unwrap();
81	    }
